    <div class="flex items-center justify-between border-b border-gray-100 dark:border-gray-800 pb-3"><h3 class="text-xs font-bold text-gray-900 dark:text-white tracking-wider flex items-center gap-2"><i class="fa-solid fa-map-location-dot text-indigo-500"></i>Detail Break Down Data Regional Sales Domestic</h3></div>
    <div class="overflow-x-auto scrollbar-thin"><table class="w-full text-left text-xs border-collapse min-w-[2600px]"><thead class="bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300 font-bold border-b border-gray-300 dark:border-gray-700 text-center"><tr><th class="p-2.5 border-r border-gray-300 dark:border-gray-700 w-10" rowspan="2">No.</th><th class="p-2.5 border-r border-gray-300 dark:border-gray-700 min-w-[110px]" rowspan="2">REGION</th><th class="p-2.5 border-r border-gray-300 dark:border-gray-700 min-w-[130px]" rowspan="2">COUNTRY/AREA</th><th class="p-2.5 border-r border-gray-300 dark:border-gray-700 min-w-[100px]" rowspan="2">CODE INV</th><th class="p-2.5 border-r border-gray-300 dark:border-gray-700 min-w-[200px]" rowspan="2">PRODUCT NAME</th><th class="p-2.5 border-r border-gray-300 dark:border-gray-700 min-w-[80px]" rowspan="2">DIV</th><th class="p-2.5 border-r border-gray-300 dark:border-gray-700 min-w-[120px]" rowspan="2">KEY PRODUCT</th><template x-for="(month, idx) in monthNames" :key="'reg-'+month"><th class="p-2 border-r border-gray-300 dark:border-gray-700 text-center" :class="idx % 2 === 0 ? 'bg-sky-50/70 dark:bg-gray-800/80' : 'bg-gray-100/70 dark:bg-gray-800/40'" colspan="3" x-text="month"></th></template><th class="p-2 border-l-2 border-primary/40 bg-primary/10 text-center font-extrabold" colspan="3">TOTAL</th></tr><tr class="bg-gray-50 dark:bg-gray-800 text-[10px]"><?php for ($i = 0; $i < 12; $i++): ?><th class="p-1 border-r border-gray-200 dark:border-gray-700 w-18 text-center">QTY (Kg)</th><th class="p-1 border-r border-gray-200 dark:border-gray-700 w-24 text-center">REVENUE (Rp)</th><th class="p-1 border-r border-gray-200 dark:border-gray-700 w-20 text-center">ASP/kg</th><?php endfor; ?><th class="p-1 border-r border-gray-200 dark:border-gray-700 w-18 text-center bg-primary/10 font-bold">QTY (Kg)</th><th class="p-1 border-r border-gray-200 dark:border-gray-700 w-24 text-center bg-primary/10 font-bold">REVENUE (Rp)</th><th class="p-1 border-r border-gray-200 dark:border-gray-700 w-20 text-center bg-primary/10 font-bold">ASP/kg</th></tr></thead><tbody class="divide-y divide-gray-200 dark:divide-gray-800 font-mono text-[11px]"><template x-if="regionalData.length === 0"><tr><td colspan="44" class="p-12 text-center text-gray-400 dark:text-gray-500"><i class="fa-solid fa-map-location-dot text-2xl mb-3"></i><p class="font-semibold text-gray-600 dark:text-gray-300">Belum ada data regional domestic</p><p class="text-xs mt-1">Upload data regional via tab <strong>Upload Data</strong>.</p></td></tr></template><template x-for="(reg, idx) in regionalData" :key="reg.id || idx"><tr class="hover:bg-gray-50 dark:hover:bg-gray-800/50"><td class="p-2 text-center border-r border-gray-200 dark:border-gray-800" x-text="idx + 1"></td><td class="p-2 font-sans font-semibold border-r border-gray-200 dark:border-gray-800 text-gray-900 dark:text-white" x-text="reg.region"></td><td class="p-2 font-sans border-r border-gray-200 dark:border-gray-800" x-text="reg.country"></td><td class="p-2 border-r border-gray-200 dark:border-gray-800" x-text="reg.id_inv"></td><td class="p-2 font-sans font-medium border-r border-gray-200 dark:border-gray-800 text-gray-900 dark:text-white" x-text="reg.product_name"></td><td class="p-2 border-r border-gray-200 dark:border-gray-800 text-center" x-text="reg.div"></td><td class="p-2 font-sans border-r border-gray-200 dark:border-gray-800" x-text="reg.key_product"></td><template x-for="col in metricCols" :key="'r-'+col.m+'-'+col.k"><td class="p-1 text-right border-r border-gray-200 dark:border-gray-800" :class="col.k === 'asp' ? 'bg-gray-50/50 dark:bg-gray-800/30' : (col.k === 'rev' ? 'text-emerald-600 dark:text-emerald-400' : '')" x-text="col.k === 'qty' ? formatNumber(reg.monthly[col.m].qty) : col.k === 'rev' ? formatNumber(reg.monthly[col.m].revenue) : formatNumber(calculateASP(reg.monthly[col.m].revenue, reg.monthly[col.m].qty))"></td></template><td class="p-2 text-right border-l-2 border-primary/30 border-r border-gray-200 dark:border-gray-800 font-bold" x-text="formatNumber(reg.total_qty)"></td><td class="p-2 text-right border-r border-gray-200 dark:border-gray-800 font-bold text-emerald-600 dark:text-emerald-400" x-text="formatNumber(reg.total_revenue)"></td><td class="p-2 text-right font-bold text-amber-600 dark:text-amber-400" x-text="formatNumber(calculateASP(reg.total_revenue, reg.total_qty))"></td></tr></template></tbody></table></div>
</div>